//! P5b parity: the library log reader (discovery → parse → finish step) against the TS oracle
//! `finishRustTranscript` (fixtures/log-reader-expected.json, generated by
//! gen-log-reader-expected.mjs from the committed fixture HOME tree) — at a HOT now (timelines
//! kept) and a COLD now (the parent loses its timeline, children keep theirs), plus the card map
//! wiring (run_cold_log_scan → put_log_session → the global timeline tier).

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use agentlens_core::delta_log::DeltaLog;
use agentlens_core::log_reader::{cold_scan, DurableState, LogTailer, ScannedFile, LOG_INGEST_VERSION};
use agentlens_core::CoreState;
use agentlens_logscan::discovery::{Env, Platform};
use serde_json::Value;

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures")
}

fn fixture_env() -> Env {
    // Darwin roots regardless of the host: the fixture tree carries `Library/Application Support`.
    Env { home: fixtures().join("logs-home"), platform: Platform::Darwin, vars: HashMap::new() }
}

fn expected() -> Value {
    serde_json::from_str(&std::fs::read_to_string(fixtures().join("log-reader-expected.json")).unwrap()).unwrap()
}

fn cards_by_id(env: &Env, now_ms: i64) -> HashMap<String, Value> {
    let (scanned, stats) = cold_scan(env, now_ms);
    // 5 discovered files (the .json with a .jsonl sibling and the events-less copilot dir are
    // NOT sessions), every one parsed, 7 cards (claude parent + 2 children + 4 singles).
    assert_eq!((stats.files, stats.parsed, stats.cards), (5, 5, 7));
    let mut out = HashMap::new();
    for s in scanned {
        assert!(s.file_size_bytes > 0, "{}", s.file);
        for c in s.cards {
            let id = c["sessionId"].as_str().unwrap().to_owned();
            assert!(out.insert(id.clone(), c).is_none(), "duplicate card {id}");
        }
    }
    out
}

fn check(got: &HashMap<String, Value>, want: &Value, label: &str) {
    let want = want.as_object().unwrap();
    assert_eq!(got.len(), want.len(), "{label}: card count");
    for (id, w) in want {
        let g = got.get(id).unwrap_or_else(|| panic!("{label}: missing card {id}"));
        if g != w {
            let gs = serde_json::to_string_pretty(g).unwrap();
            let ws = serde_json::to_string_pretty(w).unwrap();
            for (i, (a, b)) in gs.lines().zip(ws.lines()).enumerate() {
                if a != b {
                    panic!("{label}: card {id} diverges at line {i}:\n  rust: {a}\n  ts:   {b}");
                }
            }
            panic!("{label}: card {id} diverges (length)\nrust:\n{gs}\nts:\n{ws}");
        }
    }
}

#[test]
fn finish_step_matches_the_ts_oracle_hot_and_cold() {
    let e = expected();
    let env = fixture_env();
    let hot = cards_by_id(&env, e["nowHotMs"].as_i64().unwrap());
    check(&hot, &e["hot"], "hot");
    // The mixed-speed Claude session carries the blended cost as its LAST key; the parent keeps
    // its 9 entries while hot.
    let parent = &hot["cccccccc-1111-2222-3333-444444444444"];
    assert!(parent["speedBlendedCostUsd"].as_f64().unwrap() > 0.0);
    assert_eq!(parent.as_object().unwrap().keys().next_back().unwrap(), "speedBlendedCostUsd");
    assert_eq!(parent["timeline"].as_array().unwrap().len(), 9);

    let cold = cards_by_id(&env, e["nowColdMs"].as_i64().unwrap());
    check(&cold, &e["cold"], "cold");
    let parent = &cold["cccccccc-1111-2222-3333-444444444444"];
    assert_eq!(parent["timeline"].as_array().unwrap().len(), 0);
    assert_eq!(parent["timelineTruncatedCount"], 9);
    assert_eq!(parent["timelineRetainedBytes"], 0);
    // Children are never hot-age stripped (TS strips only the parent).
    assert_eq!(cold["agent-abc"]["timeline"].as_array().unwrap().len(), 1);
}

#[test]
fn run_cold_log_scan_fills_the_card_map_and_the_summary_serves_it() {
    let tmp = std::env::temp_dir().join(format!("al-logreader-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    std::fs::create_dir_all(&tmp).unwrap();
    let mut st = CoreState::open(&tmp);
    let v0 = st.data_version;
    let (scanned, stats) = cold_scan(&fixture_env(), agentlens_core::now_ms());
    assert_eq!(stats.cards, 7);
    st.ingest_scanned(scanned);
    assert_eq!(st.cards.len(), 7);
    assert!(st.data_version > v0, "put_log_session must bump data_version");
    let summary = st.session_summary(agentlens_core::now_ms() as f64);
    let ids: Vec<&str> = summary["sessions"].as_array().unwrap().iter().map(|c| c["sessionId"].as_str().unwrap()).collect();
    assert_eq!(ids.len(), 7, "{ids:?}");
    assert!(ids.contains(&"cccccccc-1111-2222-3333-444444444444") && ids.contains(&"ffffffff-1111-2222-3333-444444444444"));
    // Re-ingesting upserts (same ids, no growth); an empty sweep is a no-op.
    let v1 = st.data_version;
    st.ingest_scanned(cold_scan(&fixture_env(), agentlens_core::now_ms()).0);
    assert_eq!(st.cards.len(), 7);
    assert!(st.data_version > v1);
    let v2 = st.data_version;
    st.ingest_scanned(Vec::new());
    assert_eq!(st.data_version, v2, "an empty sweep must not bump data_version");
}

// ── The incremental tailer (P5d) ─────────────────────────────────────────────────────────────

/// A private copy of the fixture tree the test can append to.
fn scratch_home(name: &str) -> PathBuf {
    let dst = std::env::temp_dir().join(format!("al-tail-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dst);
    copy_tree(&fixtures().join("logs-home"), &dst);
    dst
}

fn copy_tree(src: &Path, dst: &Path) {
    std::fs::create_dir_all(dst).unwrap();
    for e in std::fs::read_dir(src).unwrap().flatten() {
        let p = e.path();
        let to = dst.join(e.file_name());
        if p.is_dir() { copy_tree(&p, &to) } else { std::fs::copy(&p, &to).unwrap(); }
    }
}

const CLAUDE_REL: &str = ".claude/projects/-Users-someone-proj/cccccccc-1111-2222-3333-444444444444.jsonl";

fn append(path: &Path, text: &str) {
    use std::io::Write;
    let mut f = std::fs::OpenOptions::new().append(true).open(path).unwrap();
    f.write_all(text.as_bytes()).unwrap();
}

fn turn_line(id: u32, ts: &str) -> String {
    format!(
        r#"{{"type":"assistant","timestamp":"{ts}","message":{{"id":"msg_x{id}","model":"claude-opus-5","usage":{{"input_tokens":7,"output_tokens":1,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}},"content":[{{"type":"text","text":"more {id}"}}]}}}}"#
    ) + "\n"
}

fn parent_card(scanned: &[ScannedFile]) -> &Value {
    scanned.iter().flat_map(|s| &s.cards).find(|c| c["sessionId"] == "cccccccc-1111-2222-3333-444444444444").expect("parent card")
}

#[test]
fn tailer_gates_on_stat_and_tails_growth_incrementally() {
    let home = scratch_home("grow");
    let env = Env { home: home.clone(), platform: Platform::Darwin, vars: HashMap::new() };
    let claude = home.join(CLAUDE_REL);
    let now = 1_785_578_400_000 + 600_000; // the fixture's HOT now
    let mut t = LogTailer::default();

    // Boot: the parallel cold path, every file from 0, state seeded.
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.files, s.changed, s.parsed, s.cards, s.incremental_reads, s.full_reads), (5, 5, 5, 7, 0, 5));
    let turns0 = parent_card(&scanned)["turns"].as_u64().unwrap();
    assert_eq!(t.file_state.len(), 5);
    let st0 = t.file_state[&claude];
    assert_eq!(st0.bytes_read, std::fs::metadata(&claude).unwrap().len());

    // Nothing moved → nothing touched.
    let (scanned, s) = t.sweep(&env, now);
    assert!(scanned.is_empty());
    assert_eq!((s.files, s.changed, s.parsed, s.incremental_reads, s.full_reads), (5, 0, 0, 0, 0));

    // Growth after a cold parse: no accumulator is cached for it → ONE from-0 read (which caches
    // the accumulator), only that file is re-parsed, and the card grew by one turn.
    append(&claude, &turn_line(1, "2026-08-01T10:00:08.000Z"));
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.changed, s.parsed, s.incremental_reads, s.full_reads), (1, 1, 0, 1));
    assert_eq!(scanned.len(), 1);
    assert_eq!(parent_card(&scanned)["turns"], turns0 + 1);
    assert_eq!(t.file_state[&claude].bytes_read, std::fs::metadata(&claude).unwrap().len());

    // Growth again: the accumulator is cached → an INCREMENTAL read, and the tailed card equals
    // a from-0 parse of the same bytes field for field.
    append(&claude, &turn_line(2, "2026-08-01T10:00:09.000Z"));
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.changed, s.parsed, s.incremental_reads, s.full_reads), (1, 1, 1, 0));
    let tailed = parent_card(&scanned).clone();
    assert_eq!(tailed["turns"], turns0 + 2);
    let (cold, _) = cold_scan(&env, now);
    let from_zero = parent_card(&cold);
    assert_eq!(&tailed, from_zero, "incremental tail diverged from a from-0 parse");

    // A trailing PARTIAL line is not consumed: the offset stops before it, the entry is absent,
    // and completing the line on the next sweep resumes from that offset and includes it.
    let line = turn_line(3, "2026-08-01T10:00:10.000Z");
    let (head, tail) = line.split_at(line.len() / 2);
    append(&claude, head);
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.changed, s.incremental_reads), (1, 1));
    assert_eq!(parent_card(&scanned)["turns"], turns0 + 2, "a partial line must not become an entry");
    assert_eq!(t.file_state[&claude].bytes_read + head.len() as u64, std::fs::metadata(&claude).unwrap().len());
    append(&claude, tail);
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.changed, s.incremental_reads), (1, 1));
    assert_eq!(parent_card(&scanned)["turns"], turns0 + 3);

    // A SHRUNK file (truncate/rotate) is never resumed from a stale offset: from 0 again.
    let body = std::fs::read_to_string(&claude).unwrap();
    let shorter: String = body.lines().take(6).map(|l| format!("{l}\n")).collect();
    std::fs::write(&claude, shorter).unwrap();
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.changed, s.incremental_reads, s.full_reads), (1, 0, 1));
    let (cold, _) = cold_scan(&env, now);
    assert_eq!(parent_card(&scanned), parent_card(&cold));
    assert!(parent_card(&scanned)["turns"].as_u64().unwrap() < turns0 + 3);

    // Codex files take the same path; Copilot ones are whole-file re-reads on change.
    let codex = home.join(".codex/sessions/2026/08/01/ffffffff-1111-2222-3333-444444444444.jsonl");
    append(&codex, "{\"timestamp\":\"2026-08-01T10:00:04.000Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":3000,\"cached_input_tokens\":900,\"output_tokens\":130,\"reasoning_output_tokens\":60},\"last_token_usage\":{\"input_tokens\":500}}}}\n");
    let cp = home.join(".copilot/session-state/abababab-1111-2222-3333-444444444444/events.jsonl");
    append(&cp, "{\"timestamp\":\"2026-08-01T10:00:05.000Z\",\"type\":\"assistant.message\",\"data\":{\"outputTokens\":9}}\n");
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.changed, s.parsed, s.full_reads), (2, 2, 2));
    let ids: Vec<&str> = scanned.iter().flat_map(|x| &x.cards).map(|c| c["sessionId"].as_str().unwrap()).collect();
    assert_eq!(ids, vec!["ffffffff-1111-2222-3333-444444444444", "abababab-1111-2222-3333-444444444444"]);
    let (cold, _) = cold_scan(&env, now);
    for c in scanned.iter().flat_map(|x| &x.cards) {
        let from_zero = cold.iter().flat_map(|x| &x.cards).find(|d| d["sessionId"] == c["sessionId"]).unwrap();
        assert_eq!(c, from_zero);
    }
    // Codex now has a cached accumulator: the next growth tails.
    append(&codex, "{\"timestamp\":\"2026-08-01T10:00:06.000Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":3100,\"cached_input_tokens\":900,\"output_tokens\":131,\"reasoning_output_tokens\":60},\"last_token_usage\":{\"input_tokens\":100}}}}\n");
    let (scanned, s) = t.sweep(&env, now);
    assert_eq!((s.changed, s.incremental_reads, s.full_reads), (1, 1, 0));
    let (cold, _) = cold_scan(&env, now);
    let codex_id = "ffffffff-1111-2222-3333-444444444444";
    let got = scanned.iter().flat_map(|x| &x.cards).find(|c| c["sessionId"] == codex_id).unwrap();
    let want = cold.iter().flat_map(|x| &x.cards).find(|c| c["sessionId"] == codex_id).unwrap();
    assert_eq!(got, want);
}

#[test]
fn demote_cold_timelines_keeps_only_the_k_most_recently_active() {
    let tmp = std::env::temp_dir().join(format!("al-demote-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    std::fs::create_dir_all(&tmp).unwrap();
    let mut st = CoreState::open(&tmp);
    let mk = |id: &str, start: &str, dur: f64, tl: usize| {
        serde_json::json!({ "sessionId": id, "startTime": start, "durationMs": dur,
            "timeline": (0..tl).map(|i| serde_json::json!({"spanId": format!("{id}-{i}")})).collect::<Vec<_>>() })
    };
    st.put_log_session(mk("old", "2026-08-01T10:00:00.000Z", 1000.0, 3));
    st.put_log_session(mk("newest", "2026-08-01T10:00:00.000Z", 7_200_000.0, 2)); // start+duration wins
    st.put_log_session(mk("mid", "2026-08-01T11:00:00.000Z", 0.0, 4));
    st.put_log_session(mk("nostart", "", 5.0, 1)); // unparseable start → 0 → coldest
    // A free fn, not a closure: a closure capturing `&st` would still be alive across the
    // `demote_cold_timelines(&mut self)` calls below and the borrow checker rejects it.
    fn card(st: &CoreState, id: &str) -> Value {
        st.cards.get(id).expect("a stored card")
    }
    st.demote_cold_timelines(10);
    assert_eq!(card(&st, "old")["timeline"].as_array().unwrap().len(), 3, "under the cap nothing moves");
    st.demote_cold_timelines(1);
    let tl = |st: &CoreState, id: &str| card(st, id)["timeline"].as_array().unwrap().len();
    assert_eq!((tl(&st, "newest"), tl(&st, "mid"), tl(&st, "old"), tl(&st, "nostart")), (2, 0, 0, 0));
    assert_eq!(card(&st, "old")["timelineTruncatedCount"], 3);
    assert_eq!(card(&st, "old")["timelineRetainedBytes"], 0);
    assert!(card(&st, "newest").get("timelineTruncatedCount").is_none());
    // Idempotent: a second pass finds nothing to strip and does not double-count.
    st.demote_cold_timelines(1);
    assert_eq!(card(&st, "old")["timelineTruncatedCount"], 3);
}

// ── Durable state (P5e) ──────────────────────────────────────────────────────────────────────

#[test]
fn log_ingest_version_is_in_lockstep_with_the_ts_constant() {
    // Until the cutover retires the TS engine both read each other's delta logs, so the
    // semantics stamp must be ONE number. src/collectorState.ts is the TS source of truth.
    let ts = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../src/collectorState.ts");
    let src = std::fs::read_to_string(&ts).unwrap_or_else(|e| panic!("{}: {e}", ts.display()));
    let line = src.lines().find(|l| l.starts_with("export const LOG_INGEST_VERSION")).expect("TS LOG_INGEST_VERSION line");
    let n: u64 = line.rsplit('=').next().unwrap().trim().trim_end_matches(';').parse().unwrap();
    assert_eq!(n, LOG_INGEST_VERSION, "bump rust-core's LOG_INGEST_VERSION with the TS one");
}

#[test]
fn durable_state_round_trips_offsets_and_stripped_cards_and_skips_the_cold_rescan() {
    let home = scratch_home("durable");
    let env = Env { home: home.clone(), platform: Platform::Darwin, vars: HashMap::new() };
    let data = std::env::temp_dir().join(format!("al-durable-data-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&data);
    std::fs::create_dir_all(&data).unwrap();
    let now = 1_785_578_400_000 + 600_000;

    // Run 1: a cold boot, then a forced save (what a graceful stop does).
    let state = std::sync::Mutex::new(CoreState::open(&data.join("spans")));
    let mut tailer = LogTailer::default();
    let mut durable = DurableState::open(&data);
    assert_eq!(durable.restore(&mut tailer, &mut state.lock().unwrap(), &env).unwrap(), (0, 0, 0), "nothing persisted yet");
    let (scanned, s) = tailer.sweep(&env, now);
    assert_eq!(s.full_reads, 5);
    state.lock().unwrap().ingest_scanned(scanned);
    durable.mark_dirty();
    durable.tick(&tailer, &state, true);
    assert!(data.join("log-offsets.delta.ndjson").exists() && data.join("log-sessions.delta.ndjson").exists());
    assert_eq!(std::fs::read_to_string(data.join("log-delta-version.json")).unwrap(), format!("{{\"v\":{LOG_INGEST_VERSION}}}"));
    // The persisted card is the stripped shape: no timeline/fileOps/backgroundSpans/generatedFiles.
    let cards = DeltaLog::new(&data, "log-sessions").load().unwrap();
    assert_eq!(cards.len(), 7);
    let parent = &cards["cccccccc-1111-2222-3333-444444444444"];
    assert_eq!(parent["timeline"].as_array().unwrap().len(), 0);
    assert!(parent.get("fileOps").is_none());
    assert_eq!(parent["backgroundSpans"], Value::Array(vec![]));
    assert_eq!(parent["turns"], state.lock().unwrap().cards.get("cccccccc-1111-2222-3333-444444444444").unwrap()["turns"]);
    assert_eq!(DeltaLog::new(&data, "log-offsets").load().unwrap().len(), 5);

    // Between the runs one transcript grows.
    append(&home.join(CLAUDE_REL), &turn_line(9, "2026-08-01T10:00:08.000Z"));

    // Run 2: restore → the 7 cards are back, 5 offsets import, and the boot sweep touches ONLY
    // the grown file (from 0 — the accumulator is not persisted), never the other four.
    let state2 = std::sync::Mutex::new(CoreState::open(&data.join("spans")));
    let mut tailer2 = LogTailer::default();
    let mut durable2 = DurableState::open(&data);
    let (restored, imported, skipped) = durable2.restore(&mut tailer2, &mut state2.lock().unwrap(), &env).unwrap();
    assert_eq!((restored, imported, skipped), (7, 5, 0));
    assert_eq!(state2.lock().unwrap().cards.len(), 7);
    let (scanned, s) = tailer2.sweep(&env, now);
    assert_eq!((s.files, s.changed, s.parsed, s.incremental_reads, s.full_reads), (5, 1, 1, 0, 1));
    assert_eq!(parent_card(&scanned)["turns"].as_u64().unwrap(), parent["turns"].as_u64().unwrap() + 1);
    state2.lock().unwrap().ingest_scanned(scanned);
    // Nothing else moved: the next sweep is a pure stat pass.
    let (scanned, s) = tailer2.sweep(&env, now);
    assert!(scanned.is_empty() && s.changed == 0);
    // An unchanged save costs zero bytes; the grown card costs one record.
    durable2.mark_dirty();
    let before = DeltaLog::new(&data, "log-sessions").disk_bytes();
    durable2.tick(&tailer2, &state2, true);
    let after = DeltaLog::new(&data, "log-sessions").disk_bytes();
    assert!(after > before);
    assert_eq!(DeltaLog::new(&data, "log-sessions").load().unwrap().len(), 7);

    // A rotated file (new inode at the same path) and a truncated one are NOT resumed.
    let codex = home.join(".codex/sessions/2026/08/01/ffffffff-1111-2222-3333-444444444444.jsonl");
    let body = std::fs::read(&codex).unwrap();
    // Write-then-rename, NOT remove-then-write: the replacement is created while the original
    // still holds its inode, so a different one is guaranteed on every POSIX fs. Deleting first
    // frees the inode for immediate reuse -- ext4 hands the same number straight back, so on CI
    // the "rotated" file looked unrotated and resumed (macOS never reuses, so this passed here).
    let rotated = codex.with_extension("jsonl.rotated");
    let ino_before = { use std::os::unix::fs::MetadataExt; std::fs::metadata(&codex).unwrap().ino() };
    std::fs::write(&rotated, &body).unwrap();
    std::fs::rename(&rotated, &codex).unwrap(); // same bytes, new inode
    // Assert the PRECONDITION, so a filesystem that defeats it fails here by name instead of as
    // an opaque (4, 1) ten lines below.
    let ino_after = { use std::os::unix::fs::MetadataExt; std::fs::metadata(&codex).unwrap().ino() };
    assert_ne!(ino_before, ino_after, "rotation must yield a new inode for this case to mean anything");
    let cp = home.join(".copilot/session-state/abababab-1111-2222-3333-444444444444/events.jsonl");
    let cp_body = std::fs::read_to_string(&cp).unwrap();
    std::fs::write(&cp, cp_body.lines().next().unwrap().to_owned() + "\n").unwrap(); // shrunk
    let mut tailer3 = LogTailer::default();
    let mut durable3 = DurableState::open(&data);
    let (_, imported, skipped) = durable3.restore(&mut tailer3, &mut CoreState::open(&data.join("spans")), &env).unwrap();
    // Per-case first: the tuple alone says "one file that should have skipped did not" without
    // saying WHICH, and guessing between the two cost a full CI round-trip once already.
    assert!(!tailer3.file_state.contains_key(&codex), "rotated file was resumed");
    assert!(!tailer3.file_state.contains_key(&cp), "truncated file was resumed");
    assert_eq!((imported, skipped), (3, 2));

    // A version-stale stamp restores NOTHING (cold rescan), whatever the logs hold.
    std::fs::write(data.join("log-delta-version.json"), "{\"v\":1}").unwrap();
    let mut tailer4 = LogTailer::default();
    let mut st4 = CoreState::open(&data.join("spans"));
    assert_eq!(DurableState::open(&data).restore(&mut tailer4, &mut st4, &env).unwrap(), (0, 0, 0));
    assert!(st4.cards.is_empty() && tailer4.file_state.is_empty());
}

/// P5f: the watcher names a changed file and the debounced TARGETED sweep advances its card long
/// before the 60s backstop would — and the sweep touched ONE file, not the whole tree.
#[test]
fn watcher_advances_a_card_on_growth_without_waiting_for_the_backstop() {
    use agentlens_core::log_reader::{start_sweeper, FULL_RESCAN};
    let home = scratch_home("watch");
    let env = Env { home: home.clone(), platform: Platform::Darwin, vars: HashMap::new() };
    let data = std::env::temp_dir().join(format!("al-watch-data-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&data);
    std::fs::create_dir_all(&data).unwrap();
    let claude = home.join(CLAUDE_REL);
    let sid = "cccccccc-1111-2222-3333-444444444444";

    let state = std::sync::Arc::new(std::sync::Mutex::new(CoreState::open(&data)));
    // poll_interval is the NO-watcher fallback cadence; with a watcher attached the backstop is
    // FULL_RESCAN (60s), so a card advancing within seconds can only be the targeted path.
    let (boot, handle) = start_sweeper(state.clone(), env, data.clone(), std::time::Duration::from_secs(3600)).unwrap();
    assert!(boot.watch_attached >= 1, "the fixture's claude projects root is watchable: {boot:?}");
    assert!(FULL_RESCAN.as_secs() >= 60);
    let turns0 = state.lock().unwrap().cards.get(sid).unwrap()["turns"].as_u64().unwrap();
    let version0 = state.lock().unwrap().data_version;

    // FSEvents latency + the 300ms debounce: poll the card map, bounded well under the backstop.
    append(&claude, &turn_line(9, "2026-08-01T10:00:09.000Z"));
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    let mut turns = turns0;
    while std::time::Instant::now() < deadline {
        std::thread::sleep(std::time::Duration::from_millis(100));
        turns = state.lock().unwrap().cards.get(sid).unwrap()["turns"].as_u64().unwrap();
        if turns > turns0 {
            break;
        }
    }
    assert_eq!(turns, turns0 + 1, "the watcher + targeted sweep advanced the card");
    assert!(state.lock().unwrap().data_version > version0);
    let statted_before = state.lock().unwrap().log_scan.files_statted;

    // POST /api/clear's core: the cards go NOW, the sweeper forgets every offset and re-reads
    // every file from 0 (a full sweep, all 5 fixture files statted again), and the table refills.
    state.lock().unwrap().clear_all();
    assert!(state.lock().unwrap().cards.is_empty());
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while std::time::Instant::now() < deadline && state.lock().unwrap().cards.get(sid).is_none() {
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    {
        let st = state.lock().unwrap();
        assert_eq!(st.cards.get(sid).unwrap()["turns"], turns0 + 1, "re-read from byte 0 sees the grown file");
        assert_eq!(st.log_scan.files_statted, statted_before + 5, "the post-clear sweep was FULL");
    }

    // A graceful stop flushes the durable state (offsets for the file that grew).
    // `SweeperHandle::stop()` was split into `signal()` + `join_within(Duration)` (TRDD-N60JUWU3)
    // so a real stop can bound the join; a test can just ask for a generous budget.
    handle.signal();
    assert!(handle.join_within(std::time::Duration::from_secs(10)), "sweeper did not finish its final flush in time");
    let offsets = DeltaLog::new(&data, "log-offsets").load().unwrap();
    assert_eq!(offsets[claude.to_str().unwrap()]["bytesRead"], std::fs::metadata(&claude).unwrap().len());
}

/// P5c: the account registry — the logs ingest's body-pointer events feed session → account_uuid
/// (bounded 200, MRU), and a log card built afterwards carries `accountId` iff its own sessionId
/// is known (a subagent's id never is; an import card never is); the key lands LAST, as
/// finishRustTranscript's `card.accountId = …` does.
#[test]
fn account_registry_is_fed_by_the_logs_ingest_and_stamps_log_cards_at_build_time() {
    use agentlens_core::account_registry::MAX_SESSIONS;
    use agentlens_core::log_reader::FileState;
    let data = std::env::temp_dir().join(format!("al-acct-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&data);
    std::fs::create_dir_all(&data).unwrap();
    let mut st = CoreState::open(&data);

    let logs = serde_json::json!({ "resourceLogs": [{
        "resource": { "attributes": [ { "key": "user.account_uuid", "value": { "stringValue": "acct-aaaa" } } ] },
        "scopeLogs": [{ "logRecords": [
            { "timeUnixNano": "1755600000000000000", "spanId": "0123456789abcdef",
              "attributes": [ { "key": "event.name", "value": { "stringValue": "claude_code.api_request_body" } },
                              { "key": "session.id", "value": { "stringValue": "sess-known" } },
                              { "key": "body_ref", "value": { "stringValue": "/tmp/body.json" } } ] },
            { "timeUnixNano": "1755600001000000000",
              "attributes": [ { "key": "event.name", "value": { "stringValue": "claude_code.user_prompt" } },
                              { "key": "session.id", "value": { "stringValue": "sess-other" } } ] }
        ] }]
    }] });
    agentlens_core::ingest_post(&mut st, "/v1/logs", logs.to_string().as_bytes());
    assert_eq!(st.accounts.account_for("sess-known"), Some("acct-aaaa"), "the body-pointer event fed the registry");
    assert_eq!(st.accounts.account_for("sess-other"), None, "a non-pointer event does not");

    let mk = |sid: &str| serde_json::json!({ "sessionId": sid, "source": "claude_code", "startTime": "2026-08-01T10:00:00.000Z", "timeline": [] });
    let state = FileState { bytes_read: 1, mtime_ms: 1.0, ino: 1, size: 1 };
    st.ingest_scanned(vec![ScannedFile { file: "f".into(), file_size_bytes: 1, state, cards: vec![mk("sess-known"), mk("agent-child"), mk("sess-other")] }]);
    let known = st.cards.get("sess-known").unwrap();
    assert_eq!(known["accountId"], "acct-aaaa");
    assert_eq!(known.as_object().unwrap().keys().next_back().map(String::as_str), Some("accountId"), "appended last");
    assert!(st.cards.get("agent-child").unwrap().get("accountId").is_none());
    assert!(st.cards.get("sess-other").unwrap().get("accountId").is_none());

    // Bounded + MRU: the 201st distinct session evicts the OLDEST, and a re-recorded one survives.
    for i in 0..MAX_SESSIONS {
        st.accounts.record(&format!("s{i}"), "acct-bbbb");
    }
    assert_eq!(st.accounts.len(), MAX_SESSIONS);
    assert_eq!(st.accounts.account_for("sess-known"), None, "the oldest entry was evicted");
    st.accounts.record("s0", "acct-cccc");
    st.accounts.record("s-new", "acct-dddd");
    assert_eq!(st.accounts.account_for("s0"), Some("acct-cccc"), "re-recorded = most recent, survives");
    assert_eq!(st.accounts.account_for("s1"), None, "s1 was the oldest after s0 moved");
    st.accounts.record("", "acct-eeee");
    st.accounts.record("x", "");
    assert_eq!(st.accounts.len(), MAX_SESSIONS, "empty ids are ignored");
}

// ── TRDD-ORGJ0E3G follow-up: 1h-tier cache-write round trip + message-id dedup ──────────────
//
// The review of a187815e flagged two gaps: (1) no test drove a REAL transcript through logscan
// into a serialized Card and then into session_cost — the shipped test built a Card by hand; (2)
// no test proved the 1h subtotal obeys the SAME message.id dedup as cache_create_tokens itself
// (Claude Code repeats one message's usage on every content-block row it emits — see the
// existing fixture's msg_1 in logs-home/.claude/projects/-Users-someone-proj/cccccccc-…jsonl —
// so a naive per-ROW sum would overcount both totals, not just the 1h one).

/// One user turn + one assistant JSONL line per `(message.id, cache_creation_input_tokens,
/// ephemeral_1h_input_tokens)` in `rows`. A real transcript repeats the SAME message.id across
/// content-block rows (tool_use vs text) of one message; passing the same id twice here
/// reproduces that shape.
fn write_1h_transcript(path: &Path, rows: &[(&str, f64, f64)]) {
    let mut body = String::new();
    body.push_str(
        "{\"type\":\"user\",\"timestamp\":\"2026-09-24T09:00:00.000Z\",\"cwd\":\"/Users/someone/proj\",\"entrypoint\":\"cli\",\"message\":{\"role\":\"user\",\"content\":\"fix the cache tier bug\"}}\n",
    );
    for (i, (id, create, ephemeral_1h)) in rows.iter().copied().enumerate() {
        let five_m = create - ephemeral_1h;
        let sec = 1 + i as u32;
        body.push_str(&format!(
            "{{\"type\":\"assistant\",\"timestamp\":\"2026-09-24T09:00:{sec:02}.000Z\",\"message\":{{\"id\":\"{id}\",\"model\":\"claude-opus-5-5\",\"usage\":{{\"input_tokens\":10,\"output_tokens\":5,\"cache_read_input_tokens\":1000,\"cache_creation_input_tokens\":{create},\"cache_creation\":{{\"ephemeral_5m_input_tokens\":{five_m},\"ephemeral_1h_input_tokens\":{ephemeral_1h}}}}},\"content\":[{{\"type\":\"text\",\"text\":\"turn {i}\"}}]}}}}\n"
        ));
    }
    std::fs::write(path, body).unwrap();
}

#[test]
fn cache_1h_tier_round_trips_from_transcript_through_logscan_to_session_cost() {
    let dir = std::env::temp_dir().join(format!("al-1h-roundtrip-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let file = dir.join("11111111-1111-2222-3333-444444444444.jsonl");
    // One turn, entirely on the 1h tier (800 cache-write tokens, all ephemeral_1h — the shape a
    // main-conversation subscription session produces, CLAUDE.md doctrine 3).
    write_1h_transcript(&file, &[("msg_rt1", 800.0, 800.0)]);

    let parsed = agentlens_logscan::parse_transcript(file.to_str().unwrap(), 10_000, 50_000_000)
        .unwrap()
        .expect("transcript parses");
    assert_eq!(parsed.card.cache_create_tokens, 800.0);
    assert_eq!(parsed.card.cache_create_1h_tokens, 800.0, "the whole write was on the 1h tier");
    assert!(parsed.card.cache_create_1h_tokens <= parsed.card.cache_create_tokens);

    let card_json = serde_json::to_value(&parsed.card).unwrap();
    let now = agentlens_core::now_ms() as f64;
    let detail = agentlens_core::mcp_tools::get_session_detail(&[card_json], &[], None, &parsed.card.session_id, now);
    let cost = detail["cost_usd"].as_f64().expect("cost_usd present");

    let expect = agentlens_core::pricing::calc_token_cost_usd(
        parsed.card.input_tokens,
        parsed.card.cache_read_tokens,
        parsed.card.cache_create_tokens,
        parsed.card.output_tokens,
        &parsed.card.model,
        parsed.card.cache_create_1h_tokens,
        None,
        now,
    );
    // `detail["cost_usd"]` is rounded to 4dp by get_session_detail (mcp_tools.rs js_to_fixed_num);
    // `expect` is the raw, unrounded recompute, so the two can differ by up to half a cent of a
    // cent (5e-5) purely from rounding — a tighter epsilon here is a false failure, not a stricter
    // check.
    assert!((cost - expect).abs() < 5e-5, "session_cost must actually be wired to the parsed 1h field ({cost} vs {expect})");

    // Sanity: had the split been unknown (pre-fix behavior), the cost would be strictly lower —
    // the 1h write rate is always above the 5m rate for a model with the Anthropic tier shape.
    let blind = agentlens_core::pricing::calc_token_cost_usd(
        parsed.card.input_tokens,
        parsed.card.cache_read_tokens,
        parsed.card.cache_create_tokens,
        parsed.card.output_tokens,
        &parsed.card.model,
        0.0,
        None,
        now,
    );
    assert!(expect > blind, "an all-1h card must cost more than the same tokens billed blind at 5m");
}

#[test]
fn cache_1h_tier_counts_a_repeated_message_id_once_not_once_per_content_block() {
    let dir = std::env::temp_dir().join(format!("al-1h-dedup-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let file = dir.join("22222222-1111-2222-3333-444444444444.jsonl");
    write_1h_transcript(
        &file,
        &[
            ("msg_dup", 500.0, 500.0),
            ("msg_dup", 500.0, 500.0), // same id, second content-block row — must NOT double-count
            ("msg_dup", 500.0, 500.0), // third row, same id again
            ("msg_2", 300.0, 100.0),   // a distinct message — must still count
        ],
    );

    let parsed = agentlens_logscan::parse_transcript(file.to_str().unwrap(), 10_000, 50_000_000)
        .unwrap()
        .expect("transcript parses");
    assert_eq!(parsed.card.cache_create_tokens, 800.0, "msg_dup's 3 rows must count once (500), not 1500");
    assert_eq!(parsed.card.cache_create_1h_tokens, 600.0, "the 1h subtotal obeys the same message.id dedup");
    assert!(parsed.card.cache_create_1h_tokens <= parsed.card.cache_create_tokens);
}

/// TRDD-ORGJ0E3G's actual fix, replacing the 7→8 whole-corpus version bump the review rejected
/// (bumping the version makes `restore()` discard EVERY card on a mismatch, and the cold rescan
/// that follows only rebuilds cards from transcripts STILL ON DISK — a session whose transcript
/// was already deleted or rotated would vanish from the dashboard permanently). These three tests
/// exercise the targeted mechanism `restore()` uses instead: a card missing `cacheCreate1hTokens`
/// gets its file's saved offset dropped ONLY when that file still exists, forcing exactly one
/// re-parse of that one file — every card is kept regardless, and an already-current card is
/// left completely alone.
#[test]
fn restore_reparses_once_a_stale_card_whose_file_still_exists() {
    let home = scratch_home("reparse-exists");
    let env = Env { home: home.clone(), platform: Platform::Darwin, vars: HashMap::new() };
    let data = std::env::temp_dir().join(format!("al-reparse-exists-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&data);
    std::fs::create_dir_all(&data).unwrap();
    let now = 1_785_578_400_000 + 600_000;

    // Run 1: a normal boot + forced save — the parent card is built by the CURRENT parser, so it
    // already carries cacheCreate1hTokens (the fixture transcript writes an ephemeral_1h split).
    let state = std::sync::Mutex::new(CoreState::open(&data.join("spans")));
    let mut tailer = LogTailer::default();
    let mut durable = DurableState::open(&data);
    durable.restore(&mut tailer, &mut state.lock().unwrap(), &env).unwrap();
    let (scanned, _) = tailer.sweep(&env, now);
    state.lock().unwrap().ingest_scanned(scanned);
    durable.mark_dirty();
    durable.tick(&tailer, &state, true);

    let parent_id = "cccccccc-1111-2222-3333-444444444444";
    let mut cards = DeltaLog::new(&data, "log-sessions").load().unwrap();
    let original_1h = cards[parent_id]["cacheCreate1hTokens"].as_f64().unwrap();
    assert!(original_1h > 0.0, "fixture must actually exercise the 1h tier for this test to mean anything");
    // TRDD-ORGJ0E3G review item 2: a targeted reparse must REPLACE the card, not accumulate into
    // it — capture every token bucket + the derived cost BEFORE the strip so the rebuilt card can
    // be checked for equality, not just presence, of cacheCreate1hTokens. A reparse that resumed
    // an existing accumulator instead of starting a fresh one would double these.
    let original_input = cards[parent_id]["inputTokens"].as_f64().unwrap_or(0.0);
    let original_cache_create = cards[parent_id]["cacheCreateTokens"].as_f64().unwrap();
    let original_cache_read = cards[parent_id]["cacheReadTokens"].as_f64().unwrap_or(0.0);
    let original_output = cards[parent_id]["outputTokens"].as_f64().unwrap_or(0.0);
    let original_model = cards[parent_id]["model"].as_str().unwrap_or("").to_string();
    let original_cost = agentlens_core::pricing::calc_token_cost_usd(
        original_input,
        original_cache_read,
        original_cache_create,
        original_output,
        &original_model,
        original_1h,
        None,
        now as f64,
    );
    // Simulate a card persisted by a PRE-FIX binary: strip the field.
    cards.get_mut(parent_id).unwrap().as_object_mut().unwrap().remove("cacheCreate1hTokens");
    DeltaLog::new(&data, "log-sessions").save(&cards).unwrap();

    // Run 2: restore() must keep the card (never discard it) but drop ONLY this file's offset.
    let state2 = std::sync::Mutex::new(CoreState::open(&data.join("spans2")));
    let mut tailer2 = LogTailer::default();
    let mut durable2 = DurableState::open(&data);
    let (restored, imported, skipped) = durable2.restore(&mut tailer2, &mut state2.lock().unwrap(), &env).unwrap();
    assert_eq!(restored, 7, "every card is kept, not just the ones missing the field");
    assert_eq!((imported, skipped), (4, 0), "the flagged file's offset is dropped; the other 4 import normally");
    assert!(
        state2.lock().unwrap().cards.get(parent_id).unwrap().get("cacheCreate1hTokens").is_none(),
        "the card is kept AS RESTORED — the field is backfilled by the next sweep, not here"
    );

    // The boot sweep re-parses ONLY the flagged file from 0 — not the other 4.
    let (scanned, s) = tailer2.sweep(&env, now);
    assert_eq!(s.full_reads, 1, "only the one file missing the field is cold-reparsed");
    state2.lock().unwrap().ingest_scanned(scanned);
    let rebuilt = state2.lock().unwrap().cards.get(parent_id).unwrap().clone();
    assert_eq!(rebuilt["cacheCreate1hTokens"].as_f64().unwrap(), original_1h, "the field is rebuilt with the correct value");
    // Item 2: the reparse REPLACES the card (CardStore::put is an upsert on the whole JSON blob),
    // it does not accumulate on top of the restored one — every other bucket, and the cost derived
    // from them, must come back exactly equal, not doubled.
    assert_eq!(rebuilt["cacheCreateTokens"].as_f64().unwrap(), original_cache_create, "cacheCreateTokens must not double from the targeted reparse");
    assert_eq!(rebuilt["cacheReadTokens"].as_f64().unwrap_or(0.0), original_cache_read, "cacheReadTokens must not double from the targeted reparse");
    assert_eq!(rebuilt["outputTokens"].as_f64().unwrap_or(0.0), original_output, "outputTokens must not double from the targeted reparse");
    let rebuilt_cost = agentlens_core::pricing::calc_token_cost_usd(
        rebuilt["inputTokens"].as_f64().unwrap_or(0.0),
        rebuilt["cacheReadTokens"].as_f64().unwrap_or(0.0),
        rebuilt["cacheCreateTokens"].as_f64().unwrap_or(0.0),
        rebuilt["outputTokens"].as_f64().unwrap_or(0.0),
        rebuilt["model"].as_str().unwrap_or(""),
        rebuilt["cacheCreate1hTokens"].as_f64().unwrap_or(0.0),
        None,
        now as f64,
    );
    assert!((rebuilt_cost - original_cost).abs() < 1e-9, "session cost must not double from the targeted reparse: rebuilt={rebuilt_cost} original={original_cost}");
}

#[test]
fn restore_keeps_a_stale_card_untouched_when_its_file_is_gone() {
    let home = scratch_home("reparse-gone");
    let env = Env { home: home.clone(), platform: Platform::Darwin, vars: HashMap::new() };
    let data = std::env::temp_dir().join(format!("al-reparse-gone-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&data);
    std::fs::create_dir_all(&data).unwrap();
    let now = 1_785_578_400_000 + 600_000;

    let state = std::sync::Mutex::new(CoreState::open(&data.join("spans")));
    let mut tailer = LogTailer::default();
    let mut durable = DurableState::open(&data);
    durable.restore(&mut tailer, &mut state.lock().unwrap(), &env).unwrap();
    let (scanned, _) = tailer.sweep(&env, now);
    state.lock().unwrap().ingest_scanned(scanned);
    durable.mark_dirty();
    durable.tick(&tailer, &state, true);

    let parent_id = "cccccccc-1111-2222-3333-444444444444";
    let mut cards = DeltaLog::new(&data, "log-sessions").load().unwrap();
    cards.get_mut(parent_id).unwrap().as_object_mut().unwrap().remove("cacheCreate1hTokens");
    DeltaLog::new(&data, "log-sessions").save(&cards).unwrap();

    // The whole point: the transcript this card came from is gone before the restart — exactly
    // the "Claude Code's own cleanupPeriodDays already deleted it" case a version bump would have
    // thrown away entirely (the cold rescan it triggers can only see files still on disk).
    std::fs::remove_file(home.join(CLAUDE_REL)).unwrap();

    let state2 = std::sync::Mutex::new(CoreState::open(&data.join("spans2")));
    let mut tailer2 = LogTailer::default();
    let mut durable2 = DurableState::open(&data);
    let (restored, _imported, _skipped) = durable2.restore(&mut tailer2, &mut state2.lock().unwrap(), &env).unwrap();
    assert_eq!(restored, 7, "the card survives even though its file is gone");
    let kept = state2.lock().unwrap().cards.get(parent_id).unwrap().clone();
    assert!(kept.get("cacheCreate1hTokens").is_none(), "no file to rebuild from, so the card is left exactly as restored");
    assert_eq!(kept["turns"], cards[parent_id]["turns"], "no other field was touched");

    // The boot sweep discovers only 4 files now (one deleted) and force-rereads none of them —
    // the deleted file was never flagged for reparse in the first place.
    let (scanned, s) = tailer2.sweep(&env, now);
    assert_eq!(s.files, 4);
    assert_eq!(s.full_reads, 0, "nothing is force-reread; the missing file is correctly left alone");
    assert!(scanned.is_empty());
}

